<?php
$GLOBALS['checks']=[];function check($label,$ok){global$checks;$checks[]=['test'=>$label,'ok'=>(bool)$ok];if(!$ok)throw new Exception($label);}
$seed=get_option('noor_seed_v1');check('WooCommerce actief',class_exists('WooCommerce'));check('Mollie actief',class_exists('Mollie\\WooCommerce\\Settings\\Settings')||is_plugin_active('mollie-payments-for-woocommerce/mollie-payments-for-woocommerce.php'));check('Mollie verplicht testmodus',get_option('mollie-payments-for-woocommerce_test_mode_enabled')==='yes');check('Geen bruikbare live API-sleutel',get_option('mollie-payments-for-woocommerce_live_api_key')==='');check('Inspiratie is beheerbaar inhoudstype',post_type_exists('noor_story'));check('Vragen blijven privé',!get_post_type_object('noor_inquiry')->public);check('ACF-productvelden',!!acf_get_field('field_noor_material'));check('ACF-sliderbeheer',!!acf_get_field('field_noor_hero_slides'));check('Drie beheerde homepage-slides',count(get_field('noor_hero_slides','option'))===3);check('Mailwaarschuwingen gekoppeld',in_array('noor_inquiry',BW\FormNotifications\types(),true));check('Zes WooCommerce-producten',count($seed['products'])===6);
foreach($seed['products']as$sku=>$id){$p=wc_get_product($id);check($sku.' heeft echte productfoto',$p->get_image_id()>0);check($sku.' heeft prijs',(float)$p->get_price()>0);}
$v=wc_get_product($seed['products']['vaas']);check('Vaas heeft twee bestelbare varianten',count($v->get_children())===2);$out=wc_get_product($seed['products']['mand']);check('Uitverkochte mand is geblokkeerd',!$out->is_in_stock()&&!$out->backorders_allowed());
if(!WC()->session)WC()->initialize_session();if(!WC()->customer)WC()->customer=new WC_Customer(0,true);if(!WC()->cart)WC()->initialize_cart();WC()->customer->set_billing_country('BE');WC()->customer->set_shipping_country('BE');WC()->customer->set_shipping_postcode('3000');WC()->cart->empty_cart();WC()->cart->add_to_cart($seed['products']['mok'],1);WC()->cart->calculate_totals();check('Mok winkelmand €18,50',(float)WC()->cart->get_cart_contents_total()+(float)WC()->cart->get_cart_contents_tax()>18.49);$rates=WC()->shipping()->get_packages()[0]['rates']??[];check('Verzending en afhalen onder €75',count($rates)===2);WC()->cart->empty_cart();WC()->cart->add_to_cart($seed['products']['mok'],5);WC()->cart->calculate_totals();$rates=WC()->shipping()->get_packages()[0]['rates']??[];check('Gratis verzending vanaf €75',count(array_filter($rates,fn($r)=>$r->get_method_id()==='free_shipping'))===1);check('Geen betaalmethodes zonder gekoppelde testsleutel',count(WC()->payment_gateways()->get_available_payment_gateways())===0);WC()->cart->empty_cart();echo wp_json_encode($GLOBALS['checks'],JSON_PRETTY_PRINT);
